class BoundedQueue:
    def __init__(self):
        self.items = []
        self.max_len = -1
    def put(self, item):
        self.items.append(item)
        self.max_len = max(len(self.items), self.max_len)
    def pop(self):
        self.max_len -= 1
        return self.items.pop()
    def get_last_dimensions(self):
        if self.max_len == -1:
            return (-1, -1)
        else:
            return (self.max_len, len(self.items[self.max_len]))
    def size(self):
        return len(self.items)
    def shuffle(self):
        shuffle(self.items)

